const crypto = require('crypto');

// rawBody: the request body exactly as received (a Buffer or string).
// Returns the event, or null when the signature doesn't match or the event is more than 5 minutes old.
function verify(rawBody, headers, secret) {
  const given = headers['x-replyze-signature'];
  if (typeof given !== 'string') return null;
  // Compare bytes, not strings: a non-ASCII header has more bytes than characters,
  // and timingSafeEqual throws on buffers of different lengths.
  const expected = Buffer.from('sha256=' + crypto.createHmac('sha256', secret).update(rawBody).digest('hex'));
  const received = Buffer.from(given);
  if (expected.length !== received.length || !crypto.timingSafeEqual(expected, received)) return null;

  // Signed, so take the time and the id from the body: X-Replyze-Timestamp and
  // X-Replyze-Event-Id are unsigned copies that a replayed request can change.
  const event = JSON.parse(rawBody.toString());
  const age = Math.abs(Date.now() - Date.parse(event.created_at)) / 1000;
  if (!(age <= 300)) return null;
  return event; // then skip it if you have already handled event.id
}

// $raw: the request body exactly as received.
// Returns the event, or null when the signature doesn't match or the event is more than 5 minutes old.
function verify(string $raw, mixed $signature, string $secret): ?array
{
    $expected = 'sha256=' . hash_hmac('sha256', $raw, $secret);
    if (!is_string($signature) || !hash_equals($expected, $signature)) {
        return null;
    }

    // Signed, so take the time and the id from the body: X-Replyze-Timestamp and
    // X-Replyze-Event-Id are unsigned copies that a replayed request can change.
    $event = json_decode($raw, true);
    $sent = is_string($event['created_at'] ?? null) ? strtotime($event['created_at']) : false;

    return $sent !== false && abs(time() - $sent) <= 300 ? $event : null;
}

$event = verify(file_get_contents('php://input'), $_SERVER['HTTP_X_REPLYZE_SIGNATURE'] ?? null, $secret);
if ($event === null) {
    http_response_code(401);
    exit;
}
// Then skip it if you have already handled $event['id'].
